import React, { useState } from 'react';
import styles from './Header.module.css';

const Header = () => {
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

    return (
        <header className={styles.header}>
            <div className={styles.container}>
                <div className={styles.logo}>
                    <img src="/assets/images/logo_t.png" alt="Volley Hub" className={styles.logoImage} />
                    <span className={styles.logoText}>Volley Hub</span>
                </div>

                <button
                    className={styles.mobileMenuButton}
                    onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                >
                    ☰
                </button>

                <nav className={`${styles.nav} ${mobileMenuOpen ? styles.navOpen : ''}`}>
                    <a href="/" className={styles.navLink}>Главная</a>
                    <a href="/about" className={styles.navLink}>О нас</a>
                    <a href="/notifications" className={styles.navLink}>Уведомления</a>
                    <a href="/profile" className={styles.navLink}>Профиль</a>
                    <a href="/login" className={styles.loginButton}>Войти</a>
                    <a href="/register" className={styles.registerButton}>Регистрация</a>
                </nav>
            </div>
        </header>
    );
};

export default Header;
